backend/model/10-requirements.json
{
  "contract_version": "domainry-backend-model-v1",
  "items": [
    {
      "module": "fieldservice",
      "kind": "requirement",
      "key": "customer_asset_service",
      "payload": {
        "requirement": {
          "statement": "Consumer Portal customers use a bound customer profile to read their devices and create/read only their own service requests.",
          "acceptance_criteria": [
            "Owned device request is created once",
            "Other-customer device and request are denied or concealed"
          ],
          "behaviors": [
            {
              "key": "customer_profile_records",
              "owner": "runtime_crud",
              "resource_key": "customer_profile",
              "rationale": "Runtime records own profile persistence and scoped reads",
              "trigger": "record_write",
              "scope": "single_record",
              "atomicity": "single_record",
              "failure_semantics": "reject_write"
            },
            {
              "key": "device_records",
              "owner": "runtime_crud",
              "resource_key": "device",
              "rationale": "Runtime records own device persistence and scoped reads",
              "trigger": "record_write",
              "scope": "single_record",
              "atomicity": "single_record",
              "failure_semantics": "reject_write"
            },
            {
              "key": "submit_service_request",
              "owner": "business_handler",
              "resource_key": "service_request.submit_service_request",
              "rationale": "The command must resolve the authenticated customer profile, verify device ownership, and create one request under one governed idempotent command",
              "trigger": "business_command",
              "scope": "multi_record",
              "atomicity": "multi_record",
              "failure_semantics": "rollback_command",
              "capability_gap": "Runtime CRUD cannot atomically resolve a business-profile binding and reject a mismatched device relation while controlling initial internal fields",
              "involved_objects": [
                "customer_profile",
                "device",
                "service_request"
              ],
              "read_set": [
                "customer_profile",
                "device"
              ],
              "write_set": [
                "service_request"
              ],
              "transaction_requirement": "profile/device authorization and request creation commit or reject as one Runtime unit of work"
            }
          ]
        }
      }
    },
    {
      "module": "fieldservice",
      "kind": "requirement",
      "key": "work_order_lifecycle",
      "payload": {
        "requirement": {
          "statement": "Managers dispatch and unassign requests; only the assigned technician starts repair; defined state edges and audit are enforced.",
          "acceptance_criteria": [
            "Submitted-dispatched-in_repair transitions follow the closed graph",
            "Non-assignee and illegal transitions leave state unchanged"
          ],
          "behaviors": [
            {
              "key": "dispatch_request",
              "owner": "business_handler",
              "resource_key": "service_request.dispatch_service_request",
              "rationale": "Dispatch sets the governed assignee scope owner and stages one assignment Inbox event atomically",
              "trigger": "business_command",
              "scope": "multi_record",
              "atomicity": "multi_record",
              "failure_semantics": "rollback_command",
              "capability_gap": "A system transition cannot combine assignment fields, department derivation, audit, and recipient notification",
              "involved_objects": [
                "service_request"
              ],
              "read_set": [
                "service_request"
              ],
              "write_set": [
                "service_request"
              ],
              "transaction_requirement": "assignment, state transition, audit, and notification intent commit together"
            },
            {
              "key": "unassign_request",
              "owner": "business_handler",
              "resource_key": "service_request.unassign_service_request",
              "rationale": "Unassignment clears the scope owner while applying the reverse state edge",
              "trigger": "business_command",
              "scope": "multi_record",
              "atomicity": "multi_record",
              "failure_semantics": "rollback_command",
              "capability_gap": "A system transition cannot atomically clear assignment and its derived scope facts",
              "involved_objects": [
                "service_request"
              ],
              "read_set": [
                "service_request"
              ],
              "write_set": [
                "service_request"
              ],
              "transaction_requirement": "assignment clearing and reverse transition commit together"
            },
            {
              "key": "start_repair",
              "owner": "business_handler",
              "resource_key": "service_request.start_assigned_repair",
              "rationale": "Generated principal context must match the persisted assignee before transition",
              "trigger": "business_command",
              "scope": "multi_record",
              "atomicity": "multi_record",
              "failure_semantics": "rollback_command",
              "capability_gap": "State-machine permission alone cannot express record-selected assignee equality",
              "involved_objects": [
                "service_request"
              ],
              "read_set": [
                "service_request"
              ],
              "write_set": [
                "service_request"
              ],
              "transaction_requirement": "assignee check and conditional state transition share one transaction"
            }
          ]
        }
      }
    },
    {
      "module": "fieldservice",
      "kind": "requirement",
      "key": "transactional_repair_completion",
      "payload": {
        "requirement": {
          "statement": "The assigned technician completes a repair atomically with bounded multi-line part usage, non-negative concurrent inventory decrement, immutable usage facts, a quote ledger, and audit.",
          "acceptance_criteria": [
            "All usage, stock, ledger, and completed state commit together",
            "Insufficient stock, replay, or contention never produces a partial effect"
          ],
          "behaviors": [
            {
              "key": "complete_repair",
              "owner": "business_handler",
              "resource_key": "service_request.complete_repair",
              "rationale": "One command owns multiple stock rows, usage entries, charge ledger, and terminal request state",
              "trigger": "business_command",
              "scope": "multi_record",
              "atomicity": "multi_record",
              "failure_semantics": "rollback_command",
              "capability_gap": "Runtime metadata cannot parse and settle a bounded multi-line usage payload across inventory, immutable usages, fee ledger, and request state",
              "involved_objects": [
                "service_request",
                "spare_part",
                "part_usage",
                "fee_ledger"
              ],
              "read_set": [
                "service_request",
                "spare_part"
              ],
              "write_set": [
                "service_request",
                "spare_part",
                "part_usage",
                "fee_ledger"
              ],
              "transaction_requirement": "all inventory decrements, usage rows, charge ledger, audit, and terminal state commit or roll back together"
            }
          ]
        }
      }
    },
    {
      "module": "fieldservice",
      "kind": "requirement",
      "key": "warranty_waiver",
      "payload": {
        "requirement": {
          "statement": "Assigned technicians request one warranty waiver; amounts below CNY 500 apply directly and larger amounts enter a manager approval Workflow whose terminal decision appends fee truth and notifies the requester.",
          "acceptance_criteria": [
            "Under-threshold waiver applies once",
            "At/above threshold reaches approved or rejected terminal state with exact fee and notification"
          ],
          "behaviors": [
            {
              "key": "request_waiver",
              "owner": "business_handler",
              "resource_key": "service_request.request_warranty_waiver",
              "rationale": "One command enforces assignee, uniqueness, exact threshold snapshot, direct settlement or pending process input, and notification",
              "trigger": "business_command",
              "scope": "multi_record",
              "atomicity": "multi_record",
              "failure_semantics": "rollback_command",
              "capability_gap": "Runtime CRUD cannot combine request preconditions, unique waiver creation, direct fee ledger settlement, and Inbox dispatch",
              "involved_objects": [
                "service_request",
                "warranty_waiver",
                "fee_ledger"
              ],
              "read_set": [
                "service_request",
                "warranty_waiver"
              ],
              "write_set": [
                "warranty_waiver",
                "fee_ledger"
              ],
              "transaction_requirement": "waiver uniqueness, terminal/direct ledger, audit, and notification intent commit together"
            },
            {
              "key": "approve_waiver",
              "owner": "business_handler",
              "resource_key": "warranty_waiver.approve_warranty_waiver",
              "rationale": "Approval atomically applies one pending waiver and appends its fee adjustment and requester notification",
              "trigger": "business_command",
              "scope": "multi_record",
              "atomicity": "multi_record",
              "failure_semantics": "rollback_command",
              "capability_gap": "Workflow approval needs one atomic domain command spanning waiver, ledger, audit, and Inbox",
              "involved_objects": [
                "warranty_waiver",
                "fee_ledger"
              ],
              "read_set": [
                "warranty_waiver"
              ],
              "write_set": [
                "warranty_waiver",
                "fee_ledger"
              ],
              "transaction_requirement": "approval, adjustment ledger, audit, and notification intent commit together"
            },
            {
              "key": "reject_waiver",
              "owner": "business_handler",
              "resource_key": "warranty_waiver.reject_warranty_waiver",
              "rationale": "Rejection atomically terminates one pending waiver with its reason and requester notification",
              "trigger": "business_command",
              "scope": "multi_record",
              "atomicity": "multi_record",
              "failure_semantics": "rollback_command",
              "capability_gap": "Workflow rejection needs one guarded terminal command with audit and Inbox",
              "involved_objects": [
                "warranty_waiver"
              ],
              "read_set": [
                "warranty_waiver"
              ],
              "write_set": [
                "warranty_waiver"
              ],
              "transaction_requirement": "rejection, audit, and notification intent commit together"
            },
            {
              "key": "waiver_approval_process",
              "owner": "workflow",
              "resource_key": "warranty_waiver_approval",
              "rationale": "Manager approval and rejection are durable resumable process branches",
              "trigger": "workflow_progression",
              "scope": "process",
              "atomicity": "long_running",
              "failure_semantics": "resume_process"
            }
          ]
        }
      }
    },
    {
      "module": "fieldservice",
      "kind": "requirement",
      "key": "overdue_reminders",
      "payload": {
        "requirement": {
          "statement": "A weekday morning Scheduler evaluates dispatched requests and creates at most one assigned-technician reminder per request and business date.",
          "acceptance_criteria": [
            "Eligible request produces one reminder and Inbox item",
            "Same-day replay and ineligible records produce no duplicate"
          ],
          "behaviors": [
            {
              "key": "send_overdue_reminder",
              "owner": "business_handler",
              "resource_key": "service_request.send_overdue_reminder",
              "rationale": "Per-record command checks 48-hour eligibility and persists the natural-key reminder with an Inbox intent",
              "trigger": "business_command",
              "scope": "multi_record",
              "atomicity": "multi_record",
              "failure_semantics": "rollback_command",
              "capability_gap": "Runtime Scheduler cannot own the domain eligibility, per-day compare/create, and recipient dispatch in one record command",
              "involved_objects": [
                "service_request",
                "overdue_reminder"
              ],
              "read_set": [
                "service_request",
                "overdue_reminder"
              ],
              "write_set": [
                "overdue_reminder"
              ],
              "transaction_requirement": "eligibility, reminder compare/create, audit, and notification intent commit together"
            },
            {
              "key": "overdue_record_process",
              "owner": "workflow",
              "resource_key": "overdue_service_request_scan",
              "rationale": "A record-scoped scheduled Workflow invokes the governed Action for each selected request",
              "trigger": "workflow_progression",
              "scope": "process",
              "atomicity": "long_running",
              "failure_semantics": "resume_process"
            },
            {
              "key": "weekday_overdue_schedule",
              "owner": "scheduler",
              "resource_key": "weekday_overdue_reminders",
              "rationale": "Runtime Scheduler owns weekday calendar, retry, timeout, missed-window, and restart semantics",
              "trigger": "schedule",
              "scope": "process",
              "atomicity": "long_running",
              "failure_semantics": "retry_schedule"
            }
          ]
        }
      }
    },
    {
      "module": "fieldservice",
      "kind": "requirement",
      "key": "reporting_and_export",
      "payload": {
        "requirement": {
          "statement": "Managers alone run bounded throughput and part-usage Reports and prepare requester-scoped governed work-order CSV through fixed same-Report threshold routing.",
          "acceptance_criteria": [
            "Reports return non-empty exact facts under manager scope",
            "Export follows <=1000 sync / >1000 async replay and governed download"
          ],
          "behaviors": [
            {
              "key": "request_work_order_export",
              "owner": "runtime_system_action",
              "resource_key": "report_export_audit.request_work_order_export",
              "rationale": "Runtime creates the governed audit request before the same-Report export prepare boundary",
              "trigger": "business_command",
              "scope": "single_record",
              "atomicity": "single_record",
              "failure_semantics": "rollback_command"
            }
          ]
        }
      }
    },
    {
      "module": "fieldservice",
      "kind": "requirement",
      "key": "identity_navigation_acceptance",
      "payload": {
        "requirement": {
          "statement": "Two stations, reporting line, role-differentiated menus, dual-Surface entrypoints, and non-human acceptance identities/fixtures are provisioned without project-owned credentials.",
          "acceptance_criteria": [
            "Each role receives only its persisted effective menus",
            "Portal and Business operations remain authorization-isolated"
          ],
          "behaviors": [],
          "no_executable_behavior_reason": "Foundation Identity bootstrap, roles, entrypoints, menus, and acceptance fixtures declaratively own this requirement."
        }
      }
    }
  ]
}
